// Parity tests: the browser engine must reproduce the Python pipeline exactly.
// golden.json is generated by `python ml/scripts/export_models.py`.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import * as ort from 'onnxruntime-web';
import { describe, expect, it } from 'vitest';
import { DeviceDetector } from './detector.js';
import { binResample } from './resample.js';
import { windowChannels, windowFeatures } from './signal.js';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const golden = JSON.parse(readFileSync(here('./golden.json'), 'utf8'));
const cfg = JSON.parse(readFileSync(here('../../public/models/model_config.json'), 'utf8'));
ort.env.wasm.numThreads = 1;

const maxAbsDiff = (a, b) => Math.max(...Array.from(a, (v, i) => Math.abs(v - b[i])));

describe('bin resampler', () => {
  it('matches Python bin_resample on irregular timestamps', () => {
    const { t_ms, xyz, expected } = golden.resample;
    const out = binResample(t_ms, xyz, cfg.fs);
    expect(out.length).toBe(expected.length);
    expect(maxAbsDiff(out.flat(), expected.flat())).toBeLessThan(1e-5);
  });
});

for (const [pos, g] of Object.entries(golden.positions)) {
  describe(`${pos} pipeline`, () => {
    it('window channels match Python', () => {
      for (const w of g.windows) {
        const ch = windowChannels(w.window, cfg.fs);
        ch.forEach((c, k) => expect(maxAbsDiff(c, w.channels[k])).toBeLessThan(1e-4));
      }
    });

    it('features match Python', () => {
      for (const w of g.windows) {
        const f = windowFeatures(w.window, cfg.fs, cfg.pre);
        f.forEach((v, i) => expect(Math.abs(v - w.features[i])).toBeLessThan(1e-3 * Math.max(1, Math.abs(w.features[i]))));
      }
    });

    it('ONNX models give the same probabilities as Python', async () => {
      const files = cfg.positions[pos].models;
      const load = (f) => ort.InferenceSession.create(readFileSync(here(`../../public/models/${f}`)));
      const [lgb, cnn] = await Promise.all([load(files.lightgbm), load(files.cnn)]);
      for (const w of g.windows) {
        const feats = windowFeatures(w.window, cfg.fs, cfg.pre);
        const ch = windowChannels(w.window, cfg.fs);
        const flat = new Float32Array(4 * cfg.win);
        ch.forEach((c, k) => flat.set(c, k * cfg.win));
        const lo = await lgb.run({ features: new ort.Tensor('float32', feats, [1, feats.length]) });
        const co = await cnn.run({ channels: new ort.Tensor('float32', flat, [1, 4, cfg.win]) });
        expect(Math.abs(lo.probabilities.data[1] - w.p_lightgbm)).toBeLessThan(1e-3);
        expect(Math.abs(co.prob.data[0] - w.p_cnn)).toBeLessThan(1e-3);
      }
    });

    it('streaming detector finds the same candidate peaks', () => {
      const { acc, candidate_peaks } = g.stream;
      const det = new DeviceDetector(cfg, cfg.positions[pos]);
      const found = [];
      for (const s of acc) { const c = det.push(s); if (c) found.push(c.index); }
      // Python's score_recording, like the streaming detector, only judges peaks
      // with 2.5 s of data after them, so the lists must be identical
      expect(found).toEqual(candidate_peaks);
    });
  });
}
